## Code Example

```javascript
function earliestStartup(graph, startup, t) {
  const V = graph.length;
  const indeg = new Array(V).fill(0);
  for (let u = 0; u < V; u++) for (const v of graph[u]) indeg[v]++;
  const q = [];
  const earliest = startup.slice();
  for (let i = 0; i < V; i++) if (indeg[i] === 0) q.push(i);
  let seen = 0;
  while (q.length) {
    const u = q.shift();
    seen++;
    for (const v of graph[u]) {
      earliest[v] = Math.max(earliest[v], earliest[u] + startup[v]);
      if (--indeg[v] === 0) q.push(v);
    }
  }
  if (seen !== V) throw new Error('cycle detected');
  return earliest[t];
}
```

